def _render_atomic_fact_text(atomic_facts: dict[str, object]) -> str:
    lines: list[str] = []
    field_labels = {
        "drug_name": "Drug Name",
        "dosage_form": "Dosage Form",
        "batch_number": "Batch Number",
        "manufacturing_site": "Manufacturing Site",
        "strength": "Strength",
    }
    for fact_key, label in field_labels.items():
        value = atomic_facts.get(fact_key)
        if value is None or not str(value).strip():
            continue
        lines.append(f"{label}: {value}")
    return "\n".join(lines).strip()


def _default_section_context_for_document(
    filename: str,
    source_path: str | None,
) -> dict[str, object]:
    normalized_source = (source_path or f"D:\\{filename}").lower()
    module_label = "M3" if "m3" in normalized_source else "DOC-1"
    return {
        "module_label": module_label,
        "outline_index": "3.2.S.1" if module_label == "M3" else "1.0",
        "section_title": "General Information",
        "anchor_source": "heading",
        "anchor_confidence": 0.93,
    }


def _build_parsed_document(
    *,
    filename: str,
    source_path: str | None = None,
    extra_metadata: dict[str, object] | None = None,
    content_evidence_count: int,
    content_unit_count: int,
    review_required_table_count: int,
    review_required_toc_count: int,
    toc_count: int,
    toc_sequence_count: int,
    navigation_entries: list[dict[str, object]] | None = None,
    atomic_facts: dict[str, object] | None = None,
    content_evidence: list[dict[str, object]] | None = None,
    content_units_override: list[dict[str, object]] | None = None,
    table_asts_override: list[dict[str, object]] | None = None,
    image_blocks_override: list[dict[str, object]] | None = None,
) -> dict[str, object]:
    default_section_context = _default_section_context_for_document(filename, source_path)
    generated_atomic_facts = (
        dict(atomic_facts)
        if atomic_facts is not None
        else ({"drug_name": "ExampleDrug"} if content_unit_count > 0 and content_units_override is None else {})
    )
    generated_fact_text = _render_atomic_fact_text(generated_atomic_facts) or "Drug Name: ExampleDrug"

    toc_sequences = []
    if toc_sequence_count > 0:
        toc_sequences = [
            {
                "toc_sequence_id": "tocseq_001",
                "semantic_role": "toc_outline_sequence",
                "title": "TABLE OF CONTENTS",
                "toc_ids": ["toc_001"],
                "pages": [2],
                "page_count": 1,
                "page_span": [2, 2],
                "bbox": [10.0, 120.0, 220.0, 220.0],
                "entry_count": len(navigation_entries or []),
                "root_entry_count": 1 if navigation_entries else 0,
                "leaf_entry_count": len(navigation_entries or []),
                "max_branching_factor": 0,
                "max_entry_level": 1 if navigation_entries else 0,
                "max_outline_depth": 2 if navigation_entries else 0,
                "missing_page_locator_count": 0,
                "page_locator_kinds": {"arabic": len(navigation_entries or []), "roman": 0, "unknown": 0},
                "review_required": review_required_toc_count > 0,
                "entries": navigation_entries or [],
                "root_nodes": [],
                "navigation_summary": {
                    "page_entry_spans": (
                        [
                            {
                                "page": 2,
                                "toc_ids": ["toc_001"],
                                "entry_count": len(navigation_entries or []),
                                "first_sequence_entry_index": 1 if navigation_entries else None,
                                "last_sequence_entry_index": len(navigation_entries or []) if navigation_entries else None,
                                "root_entry_indices": [1] if navigation_entries else [],
                                "cross_page_parent_entry_count": 0,
                            }
                        ]
                        if navigation_entries is not None
                        else []
                    ),
                    "root_sections": [],
                    "outline_index_lookup": {"1.0": [1]} if navigation_entries else {},
                    "outline_path_lookup": {"1.0": [1]} if navigation_entries else {},
                    "cross_page_parent_link_count": 0,
                    "cross_page_root_section_count": 0,
                },
                "toc_sequence_diagnostics": {
                    "review_required": review_required_toc_count > 0,
                    "review_item_count": review_required_toc_count,
                    "aggregated_review_item_count": 0,
                    "mixed_page_numbering": False,
                },
            }
        ]

    toc_blocks = []
    if toc_count > 0:
        toc_blocks = [
            {
                "toc_id": "toc_001",
                "page": 2,
                "bbox": [10.0, 120.0, 220.0, 220.0],
                "toc_diagnostics": {
                    "review_required": review_required_toc_count > 0,
                    "review_item_count": review_required_toc_count,
                    "aggregated_review_item_count": 0,
                    "review_items": (
                        [
                            {
                                "code": "missing_page_locator",
                                "severity": "medium",
                                "entry_index": 1,
                                "message": "TOC entry is missing a visible page locator.",
                            }
                        ]
                        if review_required_toc_count > 0
                        else []
                    ),
                    "aggregated_review_items": [],
                },
            }
        ]

    table_asts = []
    if table_asts_override is not None:
        table_asts = list(table_asts_override)
    elif review_required_table_count > 0:
        table_asts.append(
            {
                "table_id": "tbl_001",
                "page": 1,
                "bbox": [10.0, 40.0, 200.0, 100.0],
                "review_required": True,
                "review_reasons": ["Table structure is unstable."],
                "diagnostics": {
                    "possible_missing_table_content": True,
                    "candidate_count": 1,
                    "candidates": [{"row_index": 3}],
                },
            }
        )

    content_units = []
    if content_units_override is not None:
        content_units = list(content_units_override)
    elif content_unit_count > 0:
        content_units.append(
            {
                "unit_id": "cu_text_001",
                "evidence_id": "ce_text_001",
                "source_type": "text",
                "source_id": "txt_001",
                "page": 1,
                "bbox": [10.0, 10.0, 90.0, 20.0],
                "semantic_role": "text_block",
                "unit_role": "body",
                "unit_index": 1,
                "text": generated_fact_text,
                "attributes": {},
                "section_context": dict(default_section_context),
                "fact_extraction_eligible": True,
            }
        )

    for unit in content_units:
        if "section_context" not in unit:
            unit["section_context"] = dict(default_section_context)

    image_blocks = list(image_blocks_override or [])

    content_evidence_items: list[dict[str, object]] = []
    if content_evidence is not None:
        content_evidence_items = list(content_evidence)
    elif content_evidence_count > 0:
        if content_unit_count > 0:
            content_evidence_items.append(
                {
                    "evidence_id": "ce_text_001",
                    "source_type": "text",
                    "source_id": "txt_001",
                    "page": 1,
                    "bbox": [10.0, 10.0, 90.0, 20.0],
                    "semantic_role": "text_block",
                    "content_text": generated_fact_text,
                    "section_context": dict(default_section_context),
                    "segments": [{"role": "body", "text": generated_fact_text}],
                }
            )
        for table in table_asts:
            content_evidence_items.append(
                {
                    "evidence_id": f"ce_table_{table['table_id']}",
                    "source_type": "table",
                    "source_id": table["table_id"],
                    "page": table["page"],
                    "bbox": table["bbox"],
                    "semantic_role": "business_table",
                    "content_text": "Batch Inventory\nBatch Number | Strength\nBatch Number: B-001 | Strength: 100 mg",
                    "segments": [
                        {"role": "title", "text": "Batch Inventory"},
                        {"role": "header", "text": "Batch Number | Strength"},
                        {"role": "row", "text": "Batch Number: B-001 | Strength: 100 mg"},
                    ],
                }
            )
        for image in image_blocks:
            content_evidence_items.append(
                {
                    "evidence_id": f"ce_image_{image['image_id']}",
                    "source_type": "image",
                    "source_id": image["image_id"],
                    "page": image["page"],
                    "bbox": image["bbox"],
                    "semantic_role": "captioned_figure",
                    "content_text": str(image.get("title") or "Figure 1: Example figure"),
                    "segments": [
                        {"role": "caption", "text": str(image.get("title") or "Figure 1: Example figure")},
                    ],
                }
            )
        for toc in toc_blocks:
            content_evidence_items.append(
                {
                    "evidence_id": f"ce_toc_{toc['toc_id']}",
                    "source_type": "toc",
                    "source_id": toc["toc_id"],
                    "page": toc["page"],
                    "bbox": toc["bbox"],
                    "semantic_role": "toc_outline",
                    "content_text": "TABLE OF CONTENTS\n1.0 | Overview | 3",
                    "segments": [
                        {"role": "title", "text": "TABLE OF CONTENTS"},
                        {"role": "entry", "text": "1.0 | Overview | 3"},
                    ],
                }
            )

    for evidence_item in content_evidence_items:
        if str(evidence_item.get("source_type") or "").strip().lower() != "toc" and "section_context" not in evidence_item:
            evidence_item["section_context"] = dict(default_section_context)

    metadata_dict = {
        "page_count": 2,
        "table_count": len(table_asts),
        "image_count": len(image_blocks),
        "figure_count": len(image_blocks),
        "toc_count": toc_count,
        "toc_sequence_count": toc_sequence_count,
        "content_evidence_count": content_evidence_count,
        "content_unit_count": content_unit_count,
        "fact_extraction_unit_count": 1 if content_unit_count > 0 else 0,
        "review_required_table_count": review_required_table_count,
        "review_required_toc_count": review_required_toc_count,
        "toc_review_item_count": review_required_toc_count,
        "aggregated_toc_review_item_count": 0,
        "continuation_table_count": 0,
        "cross_page_table_links": 0,
        "cross_page_boundary_row_merge_count": 0,
        "low_confidence_table_count": 0,
        "diagnostic_table_count": review_required_table_count,
        **dict(extra_metadata or {}),
    }

    return {
        "filename": filename,
        "source_type": "pdf",
        "source_path": source_path or f"D:\\{filename}",
        "submission_scope_kind": "submission_pdf",
        "classification": {
            "module_label": default_section_context["module_label"],
        },
        "metadata": metadata_dict,
        "summary": metadata_dict,
        "document_ast": {
            "pages": [{"page": 1}, {"page": 2}],
            "table_refs": [table["table_id"] for table in table_asts],
            "toc_refs": [toc["toc_id"] for toc in toc_blocks],
            "toc_sequence_refs": [sequence["toc_sequence_id"] for sequence in toc_sequences],
            "image_refs": [image["image_id"] for image in image_blocks],
            "content_evidence_refs": [item["evidence_id"] for item in content_evidence_items],
            "content_unit_refs": [unit["unit_id"] for unit in content_units],
        },
        "content_units": content_units,
        "content_evidence": content_evidence_items,
        "toc_sequences": toc_sequences,
        "atomic_facts": generated_atomic_facts,
        "table_asts": table_asts,
        "toc_blocks": toc_blocks,
        "image_blocks": image_blocks,
    }


