def _find_authoritative_regulation_file(filename: str) -> Path:
    candidate_roots = [
        Path(__file__).resolve().parents[2] / "data" / "regulations",
        Path(r"D:\AutoIND-Pro\ind-compliance-ai\data\regulations"),
    ]
    for regulation_root in candidate_roots:
        if not regulation_root.exists():
            continue
        matches = sorted(regulation_root.rglob(filename))
        if matches:
            return matches[0]
    raise FileNotFoundError(f"Missing authoritative regulation file: {filename}")


def _copy_authoritative_validation_standard_util_files(
    sequence_root: Path,
    *,
    include_stf: bool = False,
    stf_stylesheet_filenames: tuple[str, ...] = (),
) -> None:
    common_files = {
        "cn-regional-1-0.xsd": Path("util") / "dtd" / "cn-regional-1-0.xsd",
        "xlink.xsd": Path("util") / "dtd" / "xlink.xsd",
        "xml.xsd": Path("util") / "dtd" / "xml.xsd",
        "ich-ectd-3-2.dtd": Path("util") / "dtd" / "ich-ectd-3-2.dtd",
        "ectd-2-0.xsl": Path("util") / "style" / "ectd-2-0.xsl",
        "cn-regional-1-0.xsl": Path("util") / "style" / "cn-regional-1-0.xsl",
    }
    conditional_stf_files = {
        "ich-stf-v2-2.dtd": Path("util") / "dtd" / "ich-stf-v2-2.dtd",
        "valid-values.xml": Path("util") / "style" / "valid-values.xml",
    }

    files_to_copy = dict(common_files)
    if include_stf:
        files_to_copy.update(conditional_stf_files)
        for filename in stf_stylesheet_filenames:
            files_to_copy[filename] = Path("util") / "style" / filename

    for filename, relative_path in files_to_copy.items():
        destination = sequence_root / relative_path
        destination.parent.mkdir(parents=True, exist_ok=True)
        destination.write_bytes(_find_authoritative_regulation_file(filename).read_bytes())


def _write_index_md5_for_file(target_file: Path, md5_file: Path) -> None:
    checksum = hashlib.md5(target_file.read_bytes()).hexdigest()
    md5_file.write_text(f"{checksum}  {target_file.name}", encoding="utf-8")


class RuleEngineProfileTests(unittest.TestCase):
    def _build_result_for_cn_regional_payload(
        self,
        cn_regional_payload: str,
        *,
        sequence_number: str = "0001",
        related_sequence: str = "0000",
        sequence_type: str = "cnsqt2",
    ) -> dict[str, object]:
        with TemporaryDirectory() as temp_dir:
            application_root = Path(temp_dir) / "x202112345"
            sequence_root = application_root / sequence_number
            cn_regional_path = sequence_root / "m1" / "cn" / "cn-regional.xml"
            cn_regional_path.parent.mkdir(parents=True, exist_ok=True)
            cn_regional_path.write_text(cn_regional_payload, encoding="utf-8")
            index_path = sequence_root / "index.xml"
            index_path.write_text(
                f"""<?xml version="1.0" encoding="UTF-8"?>
<ectd:ectd xmlns:ectd="http://www.ich.org/eCTD" xmlns:xlink="http://www.w3.org/1999/xlink">
  <envelope
    application-number="x202112345"
    sequence-number="{sequence_number}"
    related-sequence="{related_sequence}"
    sequence-type="{sequence_type}"
  />
</ectd:ectd>
""",
                encoding="utf-8",
            )
            parsed_cn_regional = parse_file(cn_regional_path)
            parsed_index = parse_file(index_path)

            return build_compliance_result_payload(
                submission_profile="FIH",
                parsed_documents=[parsed_cn_regional, parsed_index],
                consistency_rows=[],
                final_status="completed",
            )

    def _build_result_for_index_payload(
        self,
        index_payload: str,
        *,
        sequence_number: str = "0001",
        related_sequence: str = "0000",
        include_authoritative_util_files: bool = False,
    ) -> dict[str, object]:
        with TemporaryDirectory() as temp_dir:
            application_root = Path(temp_dir) / "x202112345"
            sequence_root = application_root / sequence_number
            if include_authoritative_util_files:
                _copy_authoritative_validation_standard_util_files(sequence_root)
            cn_regional_path = sequence_root / "m1" / "cn" / "cn-regional.xml"
            cn_regional_path.parent.mkdir(parents=True, exist_ok=True)
            cn_regional_path.write_text(
                f"""<?xml version="1.0" encoding="UTF-8"?>
<cn_ectd xmlns:xlink="http://www.w3.org/1999/xlink">
  <cn-envelope>
    <application-id>x202112345</application-id>
    <sequence-number>{sequence_number}</sequence-number>
  </cn-envelope>
</cn_ectd>
""",
                encoding="utf-8",
            )
            index_path = sequence_root / "index.xml"
            index_path.write_text(index_payload, encoding="utf-8")
            parsed_cn_regional = parse_file(cn_regional_path)
            parsed_index = parse_file(index_path)

            return build_compliance_result_payload(
                submission_profile="FIH",
                parsed_documents=[parsed_cn_regional, parsed_index],
                consistency_rows=[],
                final_status="completed",
            )

    def _build_result_for_stf_payload(
        self,
        stf_payload: str,
        *,
        include_authoritative_util_files: bool = False,
    ) -> dict[str, object]:
        with TemporaryDirectory() as temp_dir:
            sequence_root = Path(temp_dir) / "x202112345" / "0001"
            if include_authoritative_util_files:
                _copy_authoritative_validation_standard_util_files(sequence_root, include_stf=True)
            stf_path = sequence_root / "m5" / "53-clin-stud-rep" / "study-001.xml"
            stf_path.parent.mkdir(parents=True, exist_ok=True)
            stf_path.write_text(stf_payload, encoding="utf-8")

            parsed_stf = parse_file(stf_path)
            return build_compliance_result_payload(
                submission_profile="FIH",
                parsed_documents=[parsed_stf],
                consistency_rows=[],
                final_status="completed",
            )

    def _build_result_for_cn_regional_sequence_payloads(
        self,
        sequence_payloads: list[tuple[str, str, str]],
    ) -> dict[str, object]:
        with TemporaryDirectory() as temp_dir:
            application_root = Path(temp_dir) / "x202112345"
            parsed_documents = []
            for sequence_number, related_sequence, cn_regional_payload in sequence_payloads:
                sequence_root = application_root / sequence_number
                cn_regional_path = sequence_root / "m1" / "cn" / "cn-regional.xml"
                cn_regional_path.parent.mkdir(parents=True, exist_ok=True)
                cn_regional_path.write_text(cn_regional_payload, encoding="utf-8")
                index_path = sequence_root / "index.xml"
                index_path.write_text(
                    f"""<?xml version="1.0" encoding="UTF-8"?>
<ectd:ectd xmlns:ectd="http://www.ich.org/eCTD" xmlns:xlink="http://www.w3.org/1999/xlink">
  <envelope
    application-number="x202112345"
    sequence-number="{sequence_number}"
    related-sequence="{related_sequence}"
    sequence-type="cnsqt2"
  />
</ectd:ectd>
""",
                    encoding="utf-8",
                )
                parsed_documents.extend([parse_file(cn_regional_path), parse_file(index_path)])

            return build_compliance_result_payload(
                submission_profile="FIH",
                parsed_documents=parsed_documents,
                consistency_rows=[],
                final_status="completed",
            )

    def _build_result_for_index_sequence_payloads(
        self,
        sequence_payloads: list[tuple[str, str, str]],
    ) -> dict[str, object]:
        with TemporaryDirectory() as temp_dir:
            application_root = Path(temp_dir) / "x202112345"
            parsed_documents = []
            for sequence_number, related_sequence, index_payload in sequence_payloads:
                sequence_root = application_root / sequence_number
                cn_regional_path = sequence_root / "m1" / "cn" / "cn-regional.xml"
                cn_regional_path.parent.mkdir(parents=True, exist_ok=True)
                cn_regional_path.write_text(
                    f"""<?xml version="1.0" encoding="UTF-8"?>
<cn_ectd xmlns:xlink="http://www.w3.org/1999/xlink">
  <cn-envelope>
    <application-id>x202112345</application-id>
    <sequence-number>{sequence_number}</sequence-number>
  </cn-envelope>
</cn_ectd>
""",
                    encoding="utf-8",
                )
                index_path = sequence_root / "index.xml"
                index_path.write_text(index_payload, encoding="utf-8")
                parsed_documents.extend([parse_file(cn_regional_path), parse_file(index_path)])

            return build_compliance_result_payload(
                submission_profile="FIH",
                parsed_documents=parsed_documents,
                consistency_rows=[],
                final_status="completed",
            )

